package com.bragincad.view

import android.content.Context
import android.content.pm.ApplicationInfo
import android.graphics.*
import android.os.Debug
import android.os.SystemClock
import android.util.Log
import android.view.*
import com.bragincad.model.*
import kotlin.math.*

private data class Bounds(val left:Float,val bottom:Float,val right:Float,val top:Float) {
    fun intersects(l:Float,b:Float,r:Float,t:Float)=right>=l&&left<=r&&top>=b&&bottom<=t
}
private data class CachedGeometry(val primitive:Primitive,val bounds:Bounds,val path:Path?=null,val oval:RectF?=null)
private data class CachedText(val source:Primitive.Text,val lines:Array<String>,val unitWidths:FloatArray,val bounds:Bounds)
private data class RenderModel(val geometry:List<CachedGeometry>,val texts:List<CachedText>,val bounds:Bounds,val buildMs:Double)

class DrawingView(context:Context):View(context) {
    var model:DrawingModel?=null;set(value){field=value;renderModel=value?.let(::buildRenderModel);visibleLayers=BooleanArray(value?.layers?.size?:0){i->value?.layers?.get(i)?.initiallyVisible?:true};fitPending=true;firstRenderPending=true;measureStart=null;measureEnd=null;invalidate()}
    var onMeasurement:((distance:Double,unit:DrawingUnit,snapped:Boolean)->Unit)?=null
    var onFirstMeasurePoint:(()->Unit)?=null
    var onCanvasTap:(()->Unit)?=null
    private var renderModel:RenderModel?=null
    private var visibleLayers=BooleanArray(0)
    private val paint=Paint(Paint.ANTI_ALIAS_FLAG).apply{color=Color.rgb(20,25,31);style=Paint.Style.STROKE;strokeWidth=1.2f}
    private val measurePaint=Paint(Paint.ANTI_ALIAS_FLAG).apply{color=Color.rgb(211,47,47);style=Paint.Style.STROKE;strokeWidth=3f}
    private val textPaint=Paint(Paint.ANTI_ALIAS_FLAG).apply{color=Color.rgb(20,25,31);style=Paint.Style.FILL;typeface=Typeface.SANS_SERIF}
    private var scale=1f;private var tx=0f;private var ty=0f;private var fitPending=true
    private var firstRenderPending=true
    private var measuring=false;private var measureStart:Point2?=null;private var measureEnd:Point2?=null;private var anySnapped=false
    private var lastX=0f;private var lastY=0f;private var moved=false;private var pinched=false
    private var previousFocusX=0f;private var previousFocusY=0f
    private var backgroundColor=Color.rgb(247,247,247)
    private val frameTimes=LongArray(120);private var frameIndex=0;private var frameCount=0;private var lastProfileMs=0L
    private var lastGcCount=runtimeStat("art.gc.gc-count")
    private val capHeightRatio:Float by lazy { textPaint.textSize=100f;val rect=Rect();textPaint.getTextBounds("H",0,1,rect);(rect.height()/100f).coerceAtLeast(.5f) }
    private val gestureLogging=context.applicationInfo.flags and ApplicationInfo.FLAG_DEBUGGABLE!=0
    private val detector=ScaleGestureDetector(context,object:ScaleGestureDetector.SimpleOnScaleGestureListener(){
        override fun onScaleBegin(d:ScaleGestureDetector):Boolean{previousFocusX=d.focusX;previousFocusY=d.focusY;pinched=true;moved=true;return true}
        override fun onScale(d:ScaleGestureDetector):Boolean{val old=scale;val factor=d.scaleFactor.takeIf{it.isFinite()&&it>0f}?:return false;val next=(old*factor).coerceIn(MIN_SCALE,MAX_SCALE);val modelX=(previousFocusX-tx)/old;val modelY=(ty-previousFocusY)/old;tx=d.focusX-modelX*next;ty=d.focusY+modelY*next;scale=next;if(gestureLogging&&frameCount%30==0)Log.d(TAG,"pinch pointers=${d.currentSpan} scale=$scale factor=$factor focus=${d.focusX},${d.focusY} centroidDelta=${d.focusX-previousFocusX},${d.focusY-previousFocusY} translation=$tx,$ty");previousFocusX=d.focusX;previousFocusY=d.focusY;invalidate();return true}
        override fun onScaleEnd(d:ScaleGestureDetector){previousFocusX=d.focusX;previousFocusY=d.focusY}
    })

    fun setLayerVisible(id:Int,visible:Boolean){if(id in visibleLayers.indices){visibleLayers[id]=visible;invalidate()}}
    fun isLayerVisible(id:Int)=visibleLayers.getOrElse(id){true}
    fun startMeasurement(){measuring=true;measureStart=null;measureEnd=null;anySnapped=false;invalidate()}
    fun cancelMeasurement(){measuring=false;measureStart=null;measureEnd=null;invalidate()}
    fun fitToDrawing(){fitPending=true;invalidate()}
    fun setPalette(background:Int,foreground:Int,accent:Int){if(backgroundColor==background&&paint.color==foreground&&measurePaint.color==accent)return;backgroundColor=background;paint.color=foreground;textPaint.color=foreground;measurePaint.color=accent;invalidate()}

    override fun onTouchEvent(e:MotionEvent):Boolean{detector.onTouchEvent(e);when(e.actionMasked){MotionEvent.ACTION_DOWN->{onCanvasTap?.invoke();lastX=e.x;lastY=e.y;moved=false;pinched=false};MotionEvent.ACTION_POINTER_DOWN->{pinched=true;moved=true};MotionEvent.ACTION_MOVE->{if(!detector.isInProgress&&e.pointerCount==1){val dx=e.x-lastX;val dy=e.y-lastY;if(abs(dx)+abs(dy)>3)moved=true;if(!measuring){tx+=dx;ty+=dy;invalidate()};lastX=e.x;lastY=e.y}};MotionEvent.ACTION_POINTER_UP->{pinched=true;moved=true;val remaining=if(e.actionIndex==0)1 else 0;if(remaining<e.pointerCount){lastX=e.getX(remaining);lastY=e.getY(remaining)}};MotionEvent.ACTION_UP->{if(measuring&&!moved&&!pinched)selectMeasurePoint(e.x,e.y);pinched=false};MotionEvent.ACTION_CANCEL->{moved=true;pinched=false}};return true}

    private fun selectMeasurePoint(screenX:Float,screenY:Float){val raw=Point2(((screenX-tx)/scale).toDouble(),((ty-screenY)/scale).toDouble());val snapped=snapEndpoint(raw,(24f*resources.displayMetrics.density/scale).toDouble());val point=snapped?:raw;anySnapped=anySnapped||snapped!=null;if(measureStart==null){measureStart=point;onFirstMeasurePoint?.invoke()}else{measureEnd=point;val a=measureStart!!;onMeasurement?.invoke(hypot(point.x-a.x,point.y-a.y),model?.units?:DrawingUnit.UNKNOWN,anySnapped);measuring=false};invalidate()}
    private fun snapEndpoint(target:Point2,tolerance:Double):Point2?{val m=model?:return null;var best:Point2?=null;var bestD=tolerance*tolerance;fun candidate(x:Double,y:Double){val d=(x-target.x).pow(2)+(y-target.y).pow(2);if(d<=bestD){bestD=d;best=Point2(x,y)}};for(p in m.primitives){if(!isLayerVisible(p.layerId))continue;when(p){is Primitive.Line->{candidate(p.x1,p.y1);candidate(p.x2,p.y2)};is Primitive.Polyline->for(i in p.points.indices step 2)candidate(p.points[i],p.points[i+1]);is Primitive.Arc->{candidate(p.cx+p.radius*cos(p.start),p.cy+p.radius*sin(p.start));candidate(p.cx+p.radius*cos(p.end),p.cy+p.radius*sin(p.end))};is Primitive.Ellipse->{fun ep(a:Double){val major=hypot(p.ax,p.ay);val angle=atan2(p.ay,p.ax);val lx=major*cos(a);val ly=major*p.ratio*sin(a);candidate(p.cx+lx*cos(angle)-ly*sin(angle),p.cy+lx*sin(angle)+ly*cos(angle))};ep(p.start);ep(p.end)};else->Unit}};return best}

    override fun onDraw(c:Canvas){val wallStart=System.nanoTime();val cpuStart=Debug.threadCpuTimeNanos();super.onDraw(c);c.drawColor(backgroundColor);val rm=renderModel?:return;if(fitPending){fit(rm.bounds);fitPending=false};val inv=1f/scale.coerceAtLeast(1e-5f);val vl=(0f-tx)*inv;val vr=(width-tx)*inv;val vb=(ty-height)*inv;val vt=ty*inv;var geometryNs=0L;var textNs=0L;var visibleGeometry=0;var visibleTexts=0;c.save();c.translate(tx,ty);c.scale(scale,-scale);paint.strokeWidth=1.2f*inv;val gs=System.nanoTime();for(item in rm.geometry)if(isLayerVisible(item.primitive.layerId)&&item.bounds.intersects(vl,vb,vr,vt)){drawCached(c,item);visibleGeometry++};geometryNs=System.nanoTime()-gs;c.restore();val ts=System.nanoTime();visibleTexts=drawTexts(c,rm,vl,vb,vr,vt);textNs=System.nanoTime()-ts;drawMeasurement(c);profileFrame(wallStart,cpuStart,geometryNs,textNs,visibleGeometry,visibleTexts,rm);if(firstRenderPending){firstRenderPending=false;Log.i(TAG,"firstRenderMs=${(System.nanoTime()-wallStart)/1e6} primitives=${model?.primitives?.size} renderModelMs=${rm.buildMs}")}}

    private fun drawTexts(c:Canvas,rm:RenderModel,vl:Float,vb:Float,vr:Float,vt:Float):Int{var visible=0;for(item in rm.texts){val p=item.source;if(!isLayerVisible(p.layerId)||p.height<=0.0||!item.bounds.intersects(vl,vb,vr,vt))continue;val capPixels=(p.height*scale).toFloat();if(capPixels<1.25f)continue;val size=capPixels/capHeightRatio;textPaint.textSize=size;textPaint.textScaleX=p.widthFactor.toFloat().coerceIn(.1f,10f);val fm=textPaint.fontMetrics;val horizontal=if(p.multiline)(p.horizontal-1).mod(3)else p.horizontal;val vertical=if(p.multiline)(p.horizontal-1)/3 else p.vertical;val lineAdvance=if(p.multiline)capPixels*(5f/3f)*p.lineSpacing.toFloat() else 0f;val blockHeight=(item.lines.size-1).coerceAtLeast(0)*lineAdvance+(fm.descent-fm.ascent);val firstBaseline=if(p.multiline)when(vertical){0->-fm.ascent;1->-fm.ascent-blockHeight/2;else->-fm.ascent-blockHeight}else when(p.vertical){1->-fm.descent;2->-(fm.ascent+fm.descent)/2;3->-fm.ascent;else->0f};c.save();c.translate(tx+p.x.toFloat()*scale,ty-p.y.toFloat()*scale);c.rotate(-Math.toDegrees(p.rotation).toFloat());for(index in item.lines.indices){val width=item.unitWidths[index]*size*textPaint.textScaleX;val x=when(horizontal){1->-width/2;2->-width;else->0f};c.drawText(item.lines[index],x,firstBaseline+index*lineAdvance,textPaint)};c.restore();visible++};textPaint.textScaleX=1f;return visible}
    private fun drawCached(c:Canvas,item:CachedGeometry){val p=item.primitive;when(p){is Primitive.Line->c.drawLine(p.x1.toFloat(),p.y1.toFloat(),p.x2.toFloat(),p.y2.toFloat(),paint);is Primitive.Circle->c.drawCircle(p.cx.toFloat(),p.cy.toFloat(),p.radius.toFloat(),paint);is Primitive.Arc->c.drawArc(item.oval!!,Math.toDegrees(p.start).toFloat(),Math.toDegrees(p.end-p.start).toFloat(),false,paint);is Primitive.Polyline->c.drawPath(item.path!!,paint);is Primitive.Ellipse->{c.save();c.rotate(Math.toDegrees(atan2(p.ay,p.ax)).toFloat(),p.cx.toFloat(),p.cy.toFloat());c.drawArc(item.oval!!,Math.toDegrees(p.start).toFloat(),Math.toDegrees(p.end-p.start).toFloat(),false,paint);c.restore()};is Primitive.Text->Unit}}
    private fun drawMeasurement(c:Canvas){val a=measureStart?:return;val b=measureEnd;val ax=tx+a.x.toFloat()*scale;val ay=ty-a.y.toFloat()*scale;c.drawCircle(ax,ay,8f,measurePaint);if(b!=null){val bx=tx+b.x.toFloat()*scale;val by=ty-b.y.toFloat()*scale;c.drawLine(ax,ay,bx,by,measurePaint);c.drawCircle(bx,by,8f,measurePaint)}}

    private fun buildRenderModel(m:DrawingModel):RenderModel{val started=System.nanoTime();val geometry=ArrayList<CachedGeometry>(m.primitives.size);val texts=ArrayList<CachedText>();var reportedTexts=0;var all:Bounds?=null;fun merge(b:Bounds){val a=all;all=if(a==null)b else Bounds(min(a.left,b.left),min(a.bottom,b.bottom),max(a.right,b.right),max(a.top,b.top))};val capRatio=capHeightRatio;textPaint.textSize=1f;for(p in m.primitives){when(p){is Primitive.Text->{val decoded=if(p.multiline)MTextDecoder.decode(p.value)else DecodedMText(p.value.replace("%%d","°",true),emptySet());val lines=layoutText(decoded.plainText,p,capRatio);val widths=FloatArray(lines.size){textPaint.measureText(lines[it])};val width=max(p.boxWidth,if(widths.isEmpty())0.0 else widths.max().toDouble()*p.height*p.widthFactor/capRatio);val blockHeight=p.height*((lines.size-1).coerceAtLeast(0)*(5.0/3.0)*p.lineSpacing+1.0);val radius=hypot(width,blockHeight).coerceAtLeast(p.height);val b=Bounds((p.x-radius).toFloat(),(p.y-radius).toFloat(),(p.x+radius).toFloat(),(p.y+radius).toFloat());texts+=CachedText(p,lines,widths,b);merge(b);if(p.multiline&&reportedTexts++<12)Log.i(TAG,"textDebug raw=${p.value.take(240)} decoded=${decoded.plainText.take(240)} lines=${lines.contentToString()} height=${p.height} paintModelSize=${p.height/capRatio} capRatio=$capRatio widthFactor=${p.widthFactor} rotation=${p.rotation} attachment=${p.horizontal} boxWidth=${p.boxWidth} anchor=${p.x},${p.y} bounds=$b");if(decoded.unsupportedCommands.isNotEmpty())Log.w(TAG,"mtextUnsupported=${decoded.unsupportedCommands} raw=${p.value.take(160)} decoded=${decoded.plainText.take(160)}")};else->{val cached=cacheGeometry(p);geometry+=cached;merge(cached.bounds)}}};val bounds=all?:Bounds(0f,0f,1f,1f);val ms=(System.nanoTime()-started)/1e6;Log.i(TAG,"renderModelMs=$ms geometry=${geometry.size} texts=${texts.size}");return RenderModel(geometry,texts,bounds,ms)}
    private fun layoutText(text:String,p:Primitive.Text,capRatio:Float):Array<String>{val paragraphs=text.split('\n');if(!p.multiline||p.boxWidth<=0.0)return paragraphs.toTypedArray();textPaint.textSize=1f;val maxUnit=(p.boxWidth*capRatio/(p.height*p.widthFactor.coerceAtLeast(.1))).toFloat();val result=ArrayList<String>();for(paragraph in paragraphs){if(paragraph.isEmpty()){result+="";continue};var line="";for(word in paragraph.split(Regex("\\s+"))){val candidate=if(line.isEmpty())word else "$line $word";if(line.isNotEmpty()&&textPaint.measureText(candidate)>maxUnit){result+=line;line=word}else line=candidate};result+=line};return result.toTypedArray()}
    private fun cacheGeometry(p:Primitive):CachedGeometry=when(p){is Primitive.Line->{val b=Bounds(min(p.x1,p.x2).toFloat(),min(p.y1,p.y2).toFloat(),max(p.x1,p.x2).toFloat(),max(p.y1,p.y2).toFloat());CachedGeometry(p,b)};is Primitive.Circle->{val b=Bounds((p.cx-p.radius).toFloat(),(p.cy-p.radius).toFloat(),(p.cx+p.radius).toFloat(),(p.cy+p.radius).toFloat());CachedGeometry(p,b)};is Primitive.Arc->{val r=RectF((p.cx-p.radius).toFloat(),(p.cy-p.radius).toFloat(),(p.cx+p.radius).toFloat(),(p.cy+p.radius).toFloat());CachedGeometry(p,Bounds(r.left,r.top,r.right,r.bottom),oval=r)};is Primitive.Polyline->{val path=Path();var minX=Float.POSITIVE_INFINITY;var minY=minX;var maxX=Float.NEGATIVE_INFINITY;var maxY=maxX;if(p.points.size>=2){path.moveTo(p.points[0].toFloat(),p.points[1].toFloat());for(i in p.points.indices step 2){val x=p.points[i].toFloat();val y=p.points[i+1].toFloat();if(i>0)path.lineTo(x,y);minX=min(minX,x);minY=min(minY,y);maxX=max(maxX,x);maxY=max(maxY,y)};if(p.closed)path.close()};CachedGeometry(p,Bounds(minX,minY,maxX,maxY),path=path)};is Primitive.Ellipse->{val major=hypot(p.ax,p.ay);val r=RectF((p.cx-major).toFloat(),(p.cy-major*p.ratio).toFloat(),(p.cx+major).toFloat(),(p.cy+major*p.ratio).toFloat());CachedGeometry(p,Bounds((p.cx-major).toFloat(),(p.cy-major).toFloat(),(p.cx+major).toFloat(),(p.cy+major).toFloat()),oval=r)};is Primitive.Text->error("Text cached separately")}
    private fun fit(b:Bounds){if(b.right>b.left&&b.top>b.bottom){scale=min((width-40)/(b.right-b.left),(height-40)/(b.top-b.bottom)).coerceAtLeast(1e-5f);tx=(width-(b.left+b.right)*scale)/2;ty=(height+(b.bottom+b.top)*scale)/2}}
    private fun profileFrame(start:Long,cpuStart:Long,geometryNs:Long,textNs:Long,visibleGeometry:Int,visibleTexts:Int,rm:RenderModel){val elapsed=System.nanoTime()-start;frameTimes[frameIndex++%frameTimes.size]=elapsed;frameCount++;val now=SystemClock.uptimeMillis();if(frameCount<frameTimes.size||now-lastProfileMs<2000)return;lastProfileMs=now;val sorted=frameTimes.clone().apply{sort()};val average=frameTimes.average()/1e6;val p95=sorted[(sorted.size*.95).toInt().coerceAtMost(sorted.lastIndex)]/1e6;val p99=sorted[(sorted.size*.99).toInt().coerceAtMost(sorted.lastIndex)]/1e6;val gc=runtimeStat("art.gc.gc-count");Log.i(TAG,"frameProfile avgMs=%.2f p95Ms=%.2f p99Ms=%.2f fps=%.1f onDrawMs=%.2f geometryMs=%.2f textMs=%.2f cpuMs=%.2f visibleGeometry=%d visibleTexts=%d totalGeometry=%d totalTexts=%d gcDelta=%d pssKb=%d".format(average,p95,p99,1000.0/average,elapsed/1e6,geometryNs/1e6,textNs/1e6,(Debug.threadCpuTimeNanos()-cpuStart)/1e6,visibleGeometry,visibleTexts,rm.geometry.size,rm.texts.size,gc-lastGcCount,Debug.getPss()));lastGcCount=gc}
    private fun runtimeStat(name:String)=Debug.getRuntimeStat(name)?.toLongOrNull()?:0L
    companion object{private const val TAG="BraginCADRender";private const val MIN_SCALE=1e-5f;private const val MAX_SCALE=1e5f}
}
